#include <vector>
#include <complex>
#include <algorithm>
#include <cmath>
#include <cstddef>
#include <omp.h>

void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    const std::size_t n = x.size();
    if (n < 2) return;

    // Parallel stable sort by magnitude using "sample sort" (oversampling) + per-bucket sort + merge.
    // Correct for any OpenMP thread count (including 1), avoids concurrent writes to same locations.
    int P = 1;
#pragma omp parallel
    {
#pragma omp single
        P = omp_get_num_threads();
    }
    if (P < 1) P = 1;
    if (static_cast<std::size_t>(P) > n) P = static_cast<int>(n);

    auto mag2 = [](const std::complex<double>& z) -> double {
        const double a = z.real();
        const double b = z.imag();
        return a * a + b * b;
    };

    // For small sizes or single thread, just do a standard sort.
    if (P == 1 || n < 2048) {
        std::stable_sort(x.begin(), x.end(),
                         [&](const std::complex<double>& a, const std::complex<double>& b) {
                             const double ma = mag2(a), mb = mag2(b);
                             if (ma < mb) return true;
                             if (ma > mb) return false;
                             // Deterministic tie-breaker
                             if (a.real() < b.real()) return true;
                             if (a.real() > b.real()) return false;
                             return a.imag() < b.imag();
                         });
        return;
    }

    // Step 1: compute keys (squared magnitudes) in parallel
    std::vector<double> key(n);
#pragma omp parallel for schedule(static)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(n); ++i) {
        key[static_cast<std::size_t>(i)] = mag2(x[static_cast<std::size_t>(i)]);
    }

    // Step 2: oversample and pick splitters
    const int oversample = 8;
    const int sampleCount = std::max(P * oversample, 1);
    std::vector<double> samples(static_cast<std::size_t>(sampleCount));

#pragma omp parallel for schedule(static)
    for (int s = 0; s < sampleCount; ++s) {
        // deterministic, evenly-spaced sampling
        const std::size_t idx = static_cast<std::size_t>(
            (static_cast<long double>(s) + 0.5L) * static_cast<long double>(n) / static_cast<long double>(sampleCount)
        );
        const std::size_t i = (idx < n) ? idx : (n - 1);
        samples[static_cast<std::size_t>(s)] = key[i];
    }

    std::sort(samples.begin(), samples.end());

    std::vector<double> splitters(static_cast<std::size_t>(P - 1));
    for (int i = 1; i < P; ++i) {
        // choose splitters at regular quantiles of the sorted sample
        const std::size_t pos = static_cast<std::size_t>(
            (static_cast<long double>(i) * static_cast<long double>(sampleCount)) / static_cast<long double>(P)
        );
        const std::size_t sp = (pos < static_cast<std::size_t>(sampleCount)) ? pos : (static_cast<std::size_t>(sampleCount) - 1);
        splitters[static_cast<std::size_t>(i - 1)] = samples[sp];
    }

    // Helper: assign a key to a bucket index in [0, P-1]
    auto bucket_of = [&](double k) -> int {
        // upper_bound gives first splitter > k, so all <= splitter go to lower bucket
        return static_cast<int>(std::upper_bound(splitters.begin(), splitters.end(), k) - splitters.begin());
    };

    // Step 3: each thread counts how many elements go to each bucket (local histogram)
    std::vector<std::size_t> counts(static_cast<std::size_t>(P) * static_cast<std::size_t>(P), 0);

#pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const std::size_t t = static_cast<std::size_t>(tid);

#pragma omp for schedule(static)
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(n); ++i) {
            const double k = key[static_cast<std::size_t>(i)];
            const int b = bucket_of(k);
            counts[t * static_cast<std::size_t>(P) + static_cast<std::size_t>(b)]++;
        }
    }

    // Step 4: compute global bucket offsets and per-thread bucket offsets (exclusive scans)
    std::vector<std::size_t> bucketSizes(static_cast<std::size_t>(P), 0);
    for (int b = 0; b < P; ++b) {
        std::size_t sum = 0;
        for (int t = 0; t < P; ++t) sum += counts[static_cast<std::size_t>(t) * static_cast<std::size_t>(P) + static_cast<std::size_t>(b)];
        bucketSizes[static_cast<std::size_t>(b)] = sum;
    }

    std::vector<std::size_t> bucketBase(static_cast<std::size_t>(P), 0);
    {
        std::size_t run = 0;
        for (int b = 0; b < P; ++b) {
            bucketBase[static_cast<std::size_t>(b)] = run;
            run += bucketSizes[static_cast<std::size_t>(b)];
        }
    }

    // threadBase[t,b] = starting index in output for thread t within bucket b
    std::vector<std::size_t> threadBase(static_cast<std::size_t>(P) * static_cast<std::size_t>(P), 0);
    for (int b = 0; b < P; ++b) {
        std::size_t run = bucketBase[static_cast<std::size_t>(b)];
        for (int t = 0; t < P; ++t) {
            threadBase[static_cast<std::size_t>(t) * static_cast<std::size_t>(P) + static_cast<std::size_t>(b)] = run;
            run += counts[static_cast<std::size_t>(t) * static_cast<std::size_t>(P) + static_cast<std::size_t>(b)];
        }
    }

    // Step 5: scatter into a temporary array (each thread writes into disjoint ranges)
    std::vector<std::complex<double>> tmp(n);

#pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const std::size_t t = static_cast<std::size_t>(tid);

        // local write positions per bucket for this thread
        std::vector<std::size_t> pos(static_cast<std::size_t>(P), 0);
        for (int b = 0; b < P; ++b) {
            pos[static_cast<std::size_t>(b)] = threadBase[t * static_cast<std::size_t>(P) + static_cast<std::size_t>(b)];
        }

#pragma omp for schedule(static)
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(n); ++i) {
            const std::size_t ii = static_cast<std::size_t>(i);
            const int b = bucket_of(key[ii]);
            const std::size_t out = pos[static_cast<std::size_t>(b)]++;
            tmp[out] = x[ii];
        }
    }

    // Step 6: sort each bucket in parallel, then copy back
#pragma omp parallel for schedule(static)
    for (int b = 0; b < P; ++b) {
        const std::size_t begin = bucketBase[static_cast<std::size_t>(b)];
        const std::size_t end = begin + bucketSizes[static_cast<std::size_t>(b)];

        auto cmp = [&](const std::complex<double>& a, const std::complex<double>& b2) {
            const double ma = mag2(a), mb = mag2(b2);
            if (ma < mb) return true;
            if (ma > mb) return false;
            if (a.real() < b2.real()) return true;
            if (a.real() > b2.real()) return false;
            return a.imag() < b2.imag();
        };

        std::stable_sort(tmp.begin() + static_cast<std::ptrdiff_t>(begin),
                         tmp.begin() + static_cast<std::ptrdiff_t>(end),
                         cmp);
    }

    x.swap(tmp);
}
